export type Video = {
  id: string
  kind: Kind
  seed: number
  author: string
  /** Indexes into the kind's captions, tags and sounds, in every language. */
  caption: number
  tags: number
  sound: number
  likes: number
  comments: number
}

export type KindStats = { views: number; likes: number; ms: number }

/** What was watched: a session's, or every session's added up. */
export type FeedStats = { views: number; likes: number; ms: number; byKind: Partial<Record<Kind, KindStats>> }

/** The card shown once Claude has answered: what this wait came to. */
export type EndCard = { views: number; likes: number; seconds: number }

/** Where the feed is drawn right now: a pane, the band above the prompt, or nowhere. */
export type FeedMode = 'off' | 'pane' | 'band'

declare module 'claude-code' {
  interface PluginState {
    'brainrot-break': {
      feed: Video[]
      index: number
      liked: string[]
      mode: FeedMode
      endCard: EndCard | null
      session: FeedStats
    }
  }
}
